"""Task: Write a class `Inventory` with `add(sku, qty)`, `remove(sku, qty)` (ValueError if not enough stock, leaving stock unchanged), `set_reorder(sku, level, amount)` and `restock_report()` returning a list of (sku, on_hand, order_amount) for every sku at or below its reorder level, sorted by sku. Quantities must be positive integers (ValueError otherwise). Unknown skus have 0 on hand."""

class Inventory:
    def __init__(self):
        self._stock = {}
        self._reorder = {}

    @staticmethod
    def _check(qty):
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("quantity must be a positive integer")

    def on_hand(self, sku):
        return self._stock.get(sku, 0)

    def add(self, sku, qty):
        self._check(qty)
        self._stock[sku] = self.on_hand(sku) + qty

    def remove(self, sku, qty):
        self._check(qty)
        if self.on_hand(sku) < qty:
            raise ValueError(f"not enough {sku}: have {self.on_hand(sku)}, need {qty}")
        self._stock[sku] -= qty

    def set_reorder(self, sku, level, amount):
        self._check(amount)
        self._reorder[sku] = (level, amount)

    def restock_report(self):
        return sorted((sku, self.on_hand(sku), amount) for sku, (level, amount) in self._reorder.items()
                      if self.on_hand(sku) <= level)


import pytest


def test_add_remove():
    inv = Inventory()
    inv.add("apple", 5)
    inv.remove("apple", 2)
    assert inv.on_hand("apple") == 3


def test_not_enough():
    inv = Inventory()
    inv.add("pear", 1)
    with pytest.raises(ValueError):
        inv.remove("pear", 2)
    assert inv.on_hand("pear") == 1


def test_bad_qty():
    inv = Inventory()
    for bad in (0, -1, 1.5, True):
        with pytest.raises(ValueError):
            inv.add("x", bad)


def test_report():
    inv = Inventory()
    inv.add("b", 10)
    inv.add("a", 2)
    inv.set_reorder("a", 5, 20)
    inv.set_reorder("b", 5, 10)
    inv.set_reorder("c", 0, 3)
    assert inv.restock_report() == [("a", 2, 20), ("c", 0, 3)]


def test_report_at_level():
    inv = Inventory()
    inv.add("a", 5)
    inv.set_reorder("a", 5, 1)
    assert inv.restock_report() == [("a", 5, 1)]

"""Task: Write `checkout(items, coupons=())` where items are (name, unit_price, qty) and coupons are strings: "PCT10" (10% off the subtotal, any number of percent), "OFF5" (5 off, after percentage coupons, never below zero) and "BOGO:<name>" (every second unit of that item free). Apply BOGO first, then percentages (only the largest one counts), then fixed amounts. Return a dict {"subtotal", "discount", "total"} as Decimals rounded to cents. Unknown coupons raise ValueError."""

import re
from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def checkout(items, coupons=()):
    subtotal = sum(Decimal(str(price)) * qty for _, price, qty in items)
    bogo, pct, off = set(), Decimal(0), Decimal(0)
    for c in coupons:
        if m := re.fullmatch(r"PCT(\d+)", c):
            pct = max(pct, Decimal(m.group(1)))
        elif m := re.fullmatch(r"OFF(\d+(?:\.\d+)?)", c):
            off += Decimal(m.group(1))
        elif c.startswith("BOGO:"):
            bogo.add(c[5:])
        else:
            raise ValueError(f"unknown coupon {c!r}")
    after = subtotal
    for name, price, qty in items:
        if name in bogo:
            after -= Decimal(str(price)) * (qty // 2)
    after -= after * pct / 100
    after = max(Decimal(0), after - off)
    total = after.quantize(CENT, rounding=ROUND_HALF_UP)
    subtotal = subtotal.quantize(CENT, rounding=ROUND_HALF_UP)
    return {"subtotal": subtotal, "discount": subtotal - total, "total": total}


from decimal import Decimal

import pytest

ITEMS = [("tea", 4.50, 3), ("mug", 12, 1)]


def test_no_coupons():
    assert checkout(ITEMS) == {"subtotal": Decimal("25.50"), "discount": Decimal("0.00"), "total": Decimal("25.50")}


def test_percent_largest_only():
    assert checkout(ITEMS, ["PCT10", "PCT20"])["total"] == Decimal("20.40")


def test_order_bogo_pct_off():
    out = checkout(ITEMS, ["OFF5", "BOGO:tea", "PCT10"])
    assert out["total"] == Decimal("13.90")
    assert out["discount"] == Decimal("11.60")


def test_never_negative():
    assert checkout([("x", 1, 1)], ["OFF5"])["total"] == Decimal("0.00")


def test_unknown():
    with pytest.raises(ValueError):
        checkout(ITEMS, ["FREE"])

"""Task: Write `final_grades(scores, weights)` where scores maps student -> {category: list of scores out of 100} and weights maps category -> weight (weights must sum to 1, else ValueError). Each category average drops the lowest score when there are at least 3. A missing category counts as 0. Return student -> (percentage rounded to 1 place, letter) with A >= 90, B >= 80, C >= 70, D >= 60, else F."""

import math


def _letter(p):
    for cut, letter in ((90, "A"), (80, "B"), (70, "C"), (60, "D")):
        if p >= cut:
            return letter
    return "F"


def final_grades(scores, weights):
    if not math.isclose(sum(weights.values()), 1.0, abs_tol=1e-9):
        raise ValueError("weights must sum to 1")
    out = {}
    for student, cats in scores.items():
        total = 0.0
        for cat, w in weights.items():
            xs = sorted(cats.get(cat, []))
            if len(xs) >= 3:
                xs = xs[1:]
            avg = sum(xs) / len(xs) if xs else 0.0
            total += w * avg
        pct = round(total, 1)
        out[student] = (pct, _letter(pct))
    return out


import pytest

W = {"homework": 0.3, "exams": 0.7}


def test_basic():
    out = final_grades({"ann": {"homework": [100, 90], "exams": [90]}}, W)
    assert out == {"ann": (91.5, "A")}


def test_drop_lowest():
    out = final_grades({"bob": {"homework": [0, 80, 100], "exams": [80]}}, W)
    assert out["bob"] == (83.0, "B")


def test_missing_category():
    assert final_grades({"cy": {"homework": [100]}}, W)["cy"] == (30.0, "F")


def test_boundary():
    assert final_grades({"d": {"homework": [60], "exams": [60]}}, W)["d"] == (60.0, "D")


def test_bad_weights():
    with pytest.raises(ValueError):
        final_grades({}, {"a": 0.5, "b": 0.4})

"""Task: Write `amortization(principal, annual_rate, months)` returning the monthly payment and a schedule list of dicts {"month", "payment", "interest", "principal", "balance"} as Decimals rounded to cents. The payment uses the standard annuity formula (zero rate means principal / months); the last payment is adjusted so the balance ends at exactly 0.00."""

from decimal import ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")


def _c(x):
    return Decimal(x).quantize(CENT, rounding=ROUND_HALF_UP)


def amortization(principal, annual_rate, months):
    if months <= 0:
        raise ValueError("months must be positive")
    p = Decimal(str(principal))
    r = Decimal(str(annual_rate)) / 12
    if r == 0:
        payment = _c(p / months)
    else:
        payment = _c(p * r / (1 - (1 + r) ** -months))
    balance, rows = p, []
    for m in range(1, months + 1):
        interest = _c(balance * r)
        if m == months:
            pay = balance + interest
        else:
            pay = payment
        princ = pay - interest
        balance = balance - princ
        rows.append({"month": m, "payment": _c(pay), "interest": interest, "principal": _c(princ), "balance": _c(balance)})
    return payment, rows


from decimal import Decimal

import pytest


def test_payment():
    payment, _ = amortization(10000, 0.06, 12)
    assert payment == Decimal("860.66")


def test_ends_at_zero():
    _, rows = amortization(10000, 0.06, 12)
    assert rows[-1]["balance"] == Decimal("0.00")
    assert len(rows) == 12


def test_first_row():
    _, rows = amortization(10000, 0.06, 12)
    assert rows[0] == {"month": 1, "payment": Decimal("860.66"), "interest": Decimal("50.00"),
                       "principal": Decimal("810.66"), "balance": Decimal("9189.34")}


def test_zero_rate():
    payment, rows = amortization(1000, 0, 3)
    assert payment == Decimal("333.33")
    assert rows[-1]["payment"] == Decimal("333.34") and rows[-1]["balance"] == Decimal("0.00")


def test_bad_months():
    with pytest.raises(ValueError):
        amortization(100, 0.1, 0)

"""Task: Write `parking_fee(entry, exit)` for datetime pairs: the first 30 minutes are free; after that each started hour costs 2.50, with a daily cap of 15.00 per calendar day of the stay (a stay over several days is charged per day, each day capped, the free 30 minutes only once at the start). An exit before entry raises ValueError. Return a Decimal."""

import datetime
import math
from decimal import Decimal

RATE, CAP = Decimal("2.50"), Decimal("15.00")


def parking_fee(entry, exit):
    if exit < entry:
        raise ValueError("exit before entry")
    start = entry + datetime.timedelta(minutes=30)
    if exit <= start:
        return Decimal("0.00")
    total, cur = Decimal("0.00"), start
    while cur < exit:
        midnight = datetime.datetime.combine(cur.date() + datetime.timedelta(days=1), datetime.time())
        end = min(exit, midnight)
        hours = math.ceil((end - cur).total_seconds() / 3600)
        total += min(CAP, RATE * hours)
        cur = end
    return total


from datetime import datetime as dt
from decimal import Decimal

import pytest


def test_free():
    assert parking_fee(dt(2024, 1, 1, 10, 0), dt(2024, 1, 1, 10, 30)) == Decimal("0.00")


def test_started_hours():
    assert parking_fee(dt(2024, 1, 1, 10, 0), dt(2024, 1, 1, 10, 31)) == Decimal("2.50")
    assert parking_fee(dt(2024, 1, 1, 10, 0), dt(2024, 1, 1, 12, 45)) == Decimal("7.50")


def test_daily_cap():
    assert parking_fee(dt(2024, 1, 1, 8, 0), dt(2024, 1, 1, 20, 0)) == Decimal("15.00")


def test_multi_day():
    assert parking_fee(dt(2024, 1, 1, 22, 0), dt(2024, 1, 3, 1, 0)) == Decimal("5.00") + Decimal("15.00") + Decimal("2.50")


def test_bad_order():
    with pytest.raises(ValueError):
        parking_fee(dt(2024, 1, 2), dt(2024, 1, 1))

"""Task: Write a class `Library` with `add_book(isbn, title, copies=1)`, `checkout(isbn, member, today)` (ValueError if no copy is free or the member already has 3 books or any overdue book), `return_book(isbn, member, today)` returning the late fee (0.25 per day after the 14-day loan period, as a float rounded to 2 places), and `overdue(today)` listing (member, isbn, days_late) sorted by days late descending then member. Dates are datetime.date."""

import datetime

LOAN_DAYS = 14


class Library:
    def __init__(self):
        self.books = {}
        self.loans = []  # (member, isbn, due)

    def add_book(self, isbn, title, copies=1):
        title0, n = self.books.get(isbn, (title, 0))
        self.books[isbn] = (title0, n + copies)

    def _out(self, isbn):
        return sum(1 for _, i, _ in self.loans if i == isbn)

    def checkout(self, isbn, member, today):
        if isbn not in self.books:
            raise KeyError(isbn)
        mine = [l for l in self.loans if l[0] == member]
        if len(mine) >= 3:
            raise ValueError("loan limit reached")
        if any(due < today for _, _, due in mine):
            raise ValueError("member has overdue books")
        if self._out(isbn) >= self.books[isbn][1]:
            raise ValueError("no copy available")
        due = today + datetime.timedelta(days=LOAN_DAYS)
        self.loans.append((member, isbn, due))
        return due

    def return_book(self, isbn, member, today):
        for k, (m, i, due) in enumerate(self.loans):
            if m == member and i == isbn:
                del self.loans[k]
                return round(max(0, (today - due).days) * 0.25, 2)
        raise ValueError("no such loan")

    def overdue(self, today):
        rows = [(m, i, (today - due).days) for m, i, due in self.loans if due < today]
        return sorted(rows, key=lambda r: (-r[2], r[0]))


from datetime import date, timedelta

import pytest

D = date(2024, 3, 1)


def lib():
    l = Library()
    l.add_book("111", "Dune", copies=2)
    l.add_book("222", "Emma")
    return l


def test_checkout_and_due():
    l = lib()
    assert l.checkout("111", "ann", D) == D + timedelta(days=14)


def test_no_copies():
    l = lib()
    l.checkout("222", "ann", D)
    with pytest.raises(ValueError, match="no copy"):
        l.checkout("222", "bob", D)


def test_limit_and_overdue_block():
    l = lib()
    l.add_book("333", "X", 5)
    for _ in range(3):
        l.checkout("333", "ann", D)
    with pytest.raises(ValueError, match="limit"):
        l.checkout("111", "ann", D)
    l.checkout("111", "bob", D)
    with pytest.raises(ValueError, match="overdue"):
        l.checkout("222", "bob", D + timedelta(days=20))


def test_fee():
    l = lib()
    l.checkout("111", "ann", D)
    assert l.return_book("111", "ann", D + timedelta(days=20)) == 1.5
    l.checkout("111", "ann", D)
    assert l.return_book("111", "ann", D + timedelta(days=3)) == 0


def test_overdue_list():
    l = lib()
    l.checkout("111", "bob", D)
    l.checkout("222", "ann", D + timedelta(days=2))
    assert l.overdue(D + timedelta(days=17)) == [("bob", "111", 3), ("ann", "222", 1)]

"""Task: Write a class `Calendar` storing events (title, start, end datetimes). `add(title, start, end)` raises ValueError if end <= start or the event overlaps an existing one (touching ends are fine) unless allow_overlap=True. `on(day)` returns titles of events touching that date, sorted by start. `next_free(after, minutes)` returns the earliest datetime at or after `after` where a slot of that length is free."""

import datetime


class Calendar:
    def __init__(self):
        self.events = []

    def add(self, title, start, end, allow_overlap=False):
        if end <= start:
            raise ValueError("end must be after start")
        if not allow_overlap:
            for t, s, e in self.events:
                if start < e and s < end:
                    raise ValueError(f"overlaps {t!r}")
        self.events.append((title, start, end))
        self.events.sort(key=lambda ev: ev[1])

    def on(self, day):
        lo = datetime.datetime.combine(day, datetime.time())
        hi = lo + datetime.timedelta(days=1)
        return [t for t, s, e in self.events if s < hi and e > lo]

    def next_free(self, after, minutes):
        need = datetime.timedelta(minutes=minutes)
        cur = after
        for _, s, e in self.events:
            if e <= cur:
                continue
            if s - cur >= need:
                return cur
            cur = max(cur, e)
        return cur


from datetime import date, datetime as dt

import pytest


def cal():
    c = Calendar()
    c.add("standup", dt(2024, 5, 6, 9, 0), dt(2024, 5, 6, 9, 15))
    c.add("review", dt(2024, 5, 6, 10, 0), dt(2024, 5, 6, 11, 0))
    return c


def test_overlap_rejected():
    c = cal()
    with pytest.raises(ValueError, match="review"):
        c.add("x", dt(2024, 5, 6, 10, 30), dt(2024, 5, 6, 12, 0))


def test_touching_ok():
    c = cal()
    c.add("lunch", dt(2024, 5, 6, 11, 0), dt(2024, 5, 6, 12, 0))
    assert c.on(date(2024, 5, 6)) == ["standup", "review", "lunch"]


def test_bad_times():
    with pytest.raises(ValueError):
        cal().add("x", dt(2024, 5, 6, 9), dt(2024, 5, 6, 9))


def test_next_free():
    c = cal()
    assert c.next_free(dt(2024, 5, 6, 9, 0), 30) == dt(2024, 5, 6, 9, 15)
    assert c.next_free(dt(2024, 5, 6, 9, 0), 60) == dt(2024, 5, 6, 11, 0)


def test_multi_day_event():
    c = Calendar()
    c.add("trip", dt(2024, 5, 6, 20), dt(2024, 5, 8, 8))
    assert c.on(date(2024, 5, 7)) == ["trip"] and c.on(date(2024, 5, 9)) == []

"""Task: Write `winner(board)` for a 3x3 tic-tac-toe board given as 3 strings of "X", "O" or "." and return "X", "O", "draw" (full board, no winner) or None (game still going). Raise ValueError for impossible boards: wrong size or characters, counts where O has more marks than X or X has more than one extra, or both players winning, or a winner whose mark count is inconsistent with having just moved."""

LINES = [[(r, c) for c in range(3)] for r in range(3)] + [[(r, c) for r in range(3)] for c in range(3)] + \
    [[(i, i) for i in range(3)], [(i, 2 - i) for i in range(3)]]


def winner(board):
    if len(board) != 3 or any(len(row) != 3 or set(row) - set("XO.") for row in board):
        raise ValueError("bad board")
    x = sum(row.count("X") for row in board)
    o = sum(row.count("O") for row in board)
    if not (x == o or x == o + 1):
        raise ValueError("impossible move counts")
    wins = {p for p in "XO" for line in LINES if all(board[r][c] == p for r, c in line)}
    if len(wins) == 2:
        raise ValueError("both players win")
    if "X" in wins and x != o + 1:
        raise ValueError("X won but O moved after")
    if "O" in wins and x != o:
        raise ValueError("O won but X moved after")
    if wins:
        return wins.pop()
    return "draw" if x + o == 9 else None


import pytest


def test_row_and_diagonal():
    assert winner(["XXX", "OO.", "..."]) == "X"
    assert winner(["OX.", "XO.", "X.O"]) == "O"


def test_draw_and_open():
    assert winner(["XOX", "XOO", "OXX"]) == "draw"
    assert winner(["X..", "...", "..."]) is None


def test_bad_counts():
    with pytest.raises(ValueError):
        winner(["OO.", "...", "..."])


def test_both_win():
    with pytest.raises(ValueError):
        winner(["XXX", "OOO", "..."])


def test_bad_shape():
    with pytest.raises(ValueError):
        winner(["XX", "...", "..."])

"""Task: Write `sudoku_errors(grid)` for a 9x9 grid (lists of ints, 0 = empty) returning a sorted list of (row, col) cells that conflict with another cell in the same row, column or 3x3 box (both cells of each conflict are listed). Write `is_solved(grid)`: True only for a full grid with no conflicts. A grid of the wrong shape or with values outside 0-9 raises ValueError."""

def _check(grid):
    if len(grid) != 9 or any(len(r) != 9 for r in grid):
        raise ValueError("grid must be 9x9")
    if any(not isinstance(v, int) or not 0 <= v <= 9 for r in grid for v in r):
        raise ValueError("values must be 0-9")


def sudoku_errors(grid):
    _check(grid)
    bad = set()
    groups = [[(r, c) for c in range(9)] for r in range(9)] + [[(r, c) for r in range(9)] for c in range(9)]
    groups += [[(br + r, bc + c) for r in range(3) for c in range(3)] for br in (0, 3, 6) for bc in (0, 3, 6)]
    for g in groups:
        seen = {}
        for r, c in g:
            v = grid[r][c]
            if v:
                seen.setdefault(v, []).append((r, c))
        for cells in seen.values():
            if len(cells) > 1:
                bad.update(cells)
    return sorted(bad)


def is_solved(grid):
    return not sudoku_errors(grid) and all(v for r in grid for v in r)


import copy

import pytest

SOLVED = [
    [5, 3, 4, 6, 7, 8, 9, 1, 2], [6, 7, 2, 1, 9, 5, 3, 4, 8], [1, 9, 8, 3, 4, 2, 5, 6, 7],
    [8, 5, 9, 7, 6, 1, 4, 2, 3], [4, 2, 6, 8, 5, 3, 7, 9, 1], [7, 1, 3, 9, 2, 4, 8, 5, 6],
    [9, 6, 1, 5, 3, 7, 2, 8, 4], [2, 8, 7, 4, 1, 9, 6, 3, 5], [3, 4, 5, 2, 8, 6, 1, 7, 9],
]


def test_solved():
    assert is_solved(SOLVED) and sudoku_errors(SOLVED) == []


def test_empty_cell_not_solved():
    g = copy.deepcopy(SOLVED)
    g[0][0] = 0
    assert sudoku_errors(g) == [] and not is_solved(g)


def test_row_conflict():
    g = [[0] * 9 for _ in range(9)]
    g[0][0] = g[0][8] = 4
    assert sudoku_errors(g) == [(0, 0), (0, 8)]


def test_box_conflict():
    g = [[0] * 9 for _ in range(9)]
    g[3][3] = g[5][5] = 7
    assert sudoku_errors(g) == [(3, 3), (5, 5)]


def test_bad_grid():
    with pytest.raises(ValueError):
        sudoku_errors([[0] * 9] * 8)
    with pytest.raises(ValueError):
        sudoku_errors([[10] + [0] * 8] + [[0] * 9] * 8)

"""Task: Write `step(live)` for Conway's Game of Life on an unbounded grid, where `live` is a set of (row, col) cells; return the next generation's set. Write `run(live, n)` applying n steps and `bounds(live)` returning (min_row, min_col, max_row, max_col) or None for an empty set."""

from collections import Counter


def step(live):
    counts = Counter((r + dr, c + dc) for r, c in live for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc)
    return {cell for cell, n in counts.items() if n == 3 or (n == 2 and cell in live)}


def run(live, n):
    for _ in range(n):
        live = step(live)
    return live


def bounds(live):
    if not live:
        return None
    rows = [r for r, _ in live]
    cols = [c for _, c in live]
    return min(rows), min(cols), max(rows), max(cols)


BLINKER = {(1, 0), (1, 1), (1, 2)}
GLIDER = {(0, 1), (1, 2), (2, 0), (2, 1), (2, 2)}


def test_blinker():
    assert step(BLINKER) == {(0, 1), (1, 1), (2, 1)}
    assert run(BLINKER, 2) == BLINKER


def test_block_still():
    block = {(0, 0), (0, 1), (1, 0), (1, 1)}
    assert step(block) == block


def test_glider_moves():
    assert run(GLIDER, 4) == {(r + 1, c + 1) for r, c in GLIDER}


def test_dies():
    assert step({(0, 0)}) == set()


def test_bounds():
    assert bounds(GLIDER) == (0, 0, 2, 2)
    assert bounds(set()) is None

"""Task: Write `solve_maze(lines)` for a maze given as strings with "#" walls, "." open cells, one "S" start and one "E" exit. Return the shortest path as a list of (row, col) from S to E inclusive using up/down/left/right moves, or None if there is none. Write `draw_path(lines, path)` returning the maze with path cells (other than S and E) marked "*". Missing or repeated S or E raises ValueError."""

from collections import deque


def _find(lines, ch):
    hits = [(r, c) for r, line in enumerate(lines) for c, x in enumerate(line) if x == ch]
    if len(hits) != 1:
        raise ValueError(f"need exactly one {ch}")
    return hits[0]


def solve_maze(lines):
    start, end = _find(lines, "S"), _find(lines, "E")
    prev = {start: None}
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur == end:
            path = []
            while cur is not None:
                path.append(cur)
                cur = prev[cur]
            return path[::-1]
        r, c = cur
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < len(lines) and 0 <= nc < len(lines[nr]) and lines[nr][nc] != "#" and (nr, nc) not in prev:
                prev[(nr, nc)] = cur
                q.append((nr, nc))
    return None


def draw_path(lines, path):
    grid = [list(line) for line in lines]
    for r, c in path or []:
        if grid[r][c] == ".":
            grid[r][c] = "*"
    return ["".join(row) for row in grid]


