"""Task: Write `build_order(tasks)` where tasks maps a task name to the list of tasks it depends on. Return an order in which every task comes after its dependencies; among tasks that are ready at the same time, pick them alphabetically. Dependencies that are not keys are tasks with no dependencies of their own. A cycle raises ValueError whose message lists the tasks on the cycle joined by " -> "."""

import heapq


def build_order(tasks):
    deps = {t: set(d) for t, d in tasks.items()}
    for d in list(deps.values()):
        for x in d:
            deps.setdefault(x, set())
    users = {t: set() for t in deps}
    for t, ds in deps.items():
        for d in ds:
            users[d].add(t)
    left = {t: len(ds) for t, ds in deps.items()}
    ready = [t for t, n in left.items() if n == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        t = heapq.heappop(ready)
        order.append(t)
        for u in users[t]:
            left[u] -= 1
            if left[u] == 0:
                heapq.heappush(ready, u)
    if len(order) < len(deps):
        stuck = {t for t, n in left.items() if n}
        start = min(stuck)
        path, cur = [start], start
        while True:
            cur = min(d for d in deps[cur] if d in stuck)
            if cur in path:
                cycle = path[path.index(cur):] + [cur]
                raise ValueError("cycle: " + " -> ".join(cycle))
            path.append(cur)
    return order


import pytest


