    assert build_order({}) == []

"""Task: Write `shortest_route(roads, start, goal)` where roads is a list of (a, b, km) two-way roads. Return (total_km, [cities]) for the shortest route using Dijkstra's algorithm, or None if unreachable; start == goal gives (0, [start]). Among equal-length routes return the one whose city list is alphabetically smallest. Negative distances raise ValueError; an unknown start raises KeyError."""

import heapq
from collections import defaultdict


def shortest_route(roads, start, goal):
    graph = defaultdict(list)
    for a, b, km in roads:
        if km < 0:
            raise ValueError("negative distance")
        graph[a].append((b, km))
        graph[b].append((a, km))
    if start not in graph and start != goal:
        raise KeyError(start)
    heap = [(0, [start])]
    done = set()
    while heap:
        dist, path = heapq.heappop(heap)
        city = path[-1]
        if city in done:
            continue
        if city == goal:
            return dist, path
        done.add(city)
        for nxt, km in graph[city]:
            if nxt not in done:
                heapq.heappush(heap, (dist + km, path + [nxt]))
    return None


