"""Task: Write `rank(scores)` taking (name, score) pairs and returning (rank, name, score) rows sorted by score descending then name, using competition ranking ("1224": tied players share a rank and the next rank skips). Write `dense_rank(scores)` with dense ranking ("1223"). If a name appears more than once only its best score counts."""

def _best(scores):
    best = {}
    for name, s in scores:
        if name not in best or s > best[name]:
            best[name] = s
    return sorted(best.items(), key=lambda kv: (-kv[1], kv[0]))


def rank(scores):
    rows, prev, r = [], None, 0
    for i, (name, s) in enumerate(_best(scores), 1):
        if s != prev:
            r, prev = i, s
        rows.append((r, name, s))
    return rows


def dense_rank(scores):
    rows, prev, r = [], None, 0
    for name, s in _best(scores):
        if s != prev:
            r, prev = r + 1, s
        rows.append((r, name, s))
    return rows


