"""Task: Write `coverage_gaps(shifts, open_time, close_time, min_staff=1)` where shifts are (name, "HH:MM", "HH:MM") within one day. Return the time ranges between open and close where fewer than min_staff people are working, as ("HH:MM", "HH:MM", staff_count) tuples in order, merging adjacent ranges with the same count."""

def _m(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m


def _t(m):
    return f"{m // 60:02d}:{m % 60:02d}"


def coverage_gaps(shifts, open_time, close_time, min_staff=1):
    lo, hi = _m(open_time), _m(close_time)
    points = {lo, hi}
    spans = []
    for _, a, b in shifts:
        a, b = max(_m(a), lo), min(_m(b), hi)
        if a < b:
            spans.append((a, b))
            points.update((a, b))
    edges = sorted(points)
    out = []
    for a, b in zip(edges, edges[1:]):
        n = sum(1 for s, e in spans if s <= a and e >= b)
        if n < min_staff:
            if out and out[-1][1] == a and out[-1][2] == n:
                out[-1] = (out[-1][0], b, n)
            else:
                out.append((a, b, n))
    return [(_t(a), _t(b), n) for a, b, n in out]


