"""Task: Write `flatten(d, sep=".")` that turns a nested dict into a flat dict with joined keys ({"a": {"b": 1}} -> {"a.b": 1}); lists are kept as values and empty dicts become an empty-dict value at their key. Write `unflatten(flat, sep=".")` for the reverse; it raises ValueError when a key is both a value and a parent (e.g. "a" and "a.b")."""

def flatten(d, sep="."):
    out = {}

    def walk(prefix, value):
        if isinstance(value, dict) and value:
            for k, v in value.items():
                walk(f"{prefix}{sep}{k}" if prefix else str(k), v)
        else:
            out[prefix] = value

    for k, v in d.items():
        walk(str(k), v)
    return out


def unflatten(flat, sep="."):
    root = {}
    for key in sorted(flat, key=lambda k: k.count(sep)):
        parts = key.split(sep)
        cur = root
        for p in parts[:-1]:
            nxt = cur.setdefault(p, {})
            if not isinstance(nxt, dict):
                raise ValueError(f"{key!r} conflicts with a value at {p!r}")
            cur = nxt
        if parts[-1] in cur and isinstance(cur[parts[-1]], dict) and cur[parts[-1]]:
            raise ValueError(f"{key!r} is also a parent")
        cur[parts[-1]] = flat[key]
    return root


