"""Task: Write `deep_merge(base, override)` that returns a new dict: keys from override replace those in base, except that when both values are dicts they are merged recursively. Neither input may be modified. A value of None in override deletes the key from the result."""

import copy


def deep_merge(base, override):
    out = copy.deepcopy(base)
    for k, v in override.items():
        if v is None:
            out.pop(k, None)
        elif isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = deep_merge(out[k], v)
        else:
            out[k] = copy.deepcopy(v)
    return out


