"""Task: Write `get_path(obj, path, default=None)` that reads values from nested dicts and lists with paths like "users[0].name" or "a.b[2][1]" and returns default when any step is missing (missing key, index out of range, wrong type). Write `set_path(obj, path, value)` that sets the value in place, creating dicts for missing keys; list indices must already exist (IndexError otherwise)."""

import re

_TOKEN = re.compile(r"([^.\[\]]+)|\[(-?\d+)\]")


def _steps(path):
    steps, pos = [], 0
    for m in _TOKEN.finditer(path):
        steps.append(m.group(1) if m.group(1) is not None else int(m.group(2)))
    if not steps:
        raise ValueError(f"empty path: {path!r}")
    return steps


def get_path(obj, path, default=None):
    cur = obj
    for s in _steps(path):
        try:
            if isinstance(s, int):
                if not isinstance(cur, list):
                    return default
                cur = cur[s]
            else:
                if not isinstance(cur, dict) or s not in cur:
                    return default
                cur = cur[s]
        except IndexError:
            return default
    return cur


def set_path(obj, path, value):
    steps = _steps(path)
    cur = obj
    for s, nxt in zip(steps, steps[1:]):
        if isinstance(s, int):
            cur = cur[s]
        else:
            if s not in cur:
                cur[s] = [] if isinstance(nxt, int) else {}
            cur = cur[s]
    last = steps[-1]
    if isinstance(last, int):
        cur[last] = value
    else:
        cur[last] = value


