"""Task: Write `summarize(records, by, field)` that groups a list of dicts by the value of key `by` and returns a dict mapping each group to {"count", "sum", "min", "max", "mean"} of `field` (mean rounded to 2 places). Records missing `field` or with a None value are counted in "missing" for their group and left out of the numbers; a group with no numeric values has None for sum, min, max and mean. Groups appear in order of first appearance."""

def summarize(records, by, field):
    groups = {}
    for r in records:
        g = groups.setdefault(r.get(by), {"values": [], "missing": 0})
        v = r.get(field)
        if v is None:
            g["missing"] += 1
        else:
            g["values"].append(v)
    out = {}
    for key, g in groups.items():
        vs = g["values"]
        out[key] = {
            "count": len(vs),
            "sum": sum(vs) if vs else None,
            "min": min(vs) if vs else None,
            "max": max(vs) if vs else None,
            "mean": round(sum(vs) / len(vs), 2) if vs else None,
            "missing": g["missing"],
        }
    return out


