"""Task: Write `diff_records(old, new, key="id")` that compares two lists of dicts identified by `key` and returns {"added": [...], "removed": [...], "changed": [...]}: added and removed are the full records (in the order of the list they come from), and changed is a list of {"key": k, "changes": {field: (old_value, new_value)}} for records whose other fields differ, including fields that appear or disappear (shown as None). Duplicate keys within one list raise ValueError."""

def _index(rows, key):
    out = {}
    for r in rows:
        k = r[key]
        if k in out:
            raise ValueError(f"duplicate key {k!r}")
        out[k] = r
    return out


def diff_records(old, new, key="id"):
    a, b = _index(old, key), _index(new, key)
    added = [r for r in new if r[key] not in a]
    removed = [r for r in old if r[key] not in b]
    changed = []
    for r in new:
        k = r[key]
        if k not in a:
            continue
        before = a[k]
        fields = [f for f in list(before) + [f for f in r if f not in before] if f != key]
        changes = {f: (before.get(f), r.get(f)) for f in fields if before.get(f) != r.get(f) or (f in before) != (f in r)}
        if changes:
            changed.append({"key": k, "changes": changes})
    return {"added": added, "removed": removed, "changed": changed}


