"""Task: Write `pivot(rows, row_key, col_key, value_key)` that builds a pivot table from a list of dicts: a dict of dicts summing value_key for each (row, column) pair, with every row containing every column seen anywhere (0 where there is no data), plus a "total" column per row and a "total" row with column sums. Rows and columns are sorted."""

def pivot(rows, row_key, col_key, value_key):
    cols = sorted({r[col_key] for r in rows})
    names = sorted({r[row_key] for r in rows})
    table = {n: {c: 0 for c in cols} for n in names}
    for r in rows:
        table[r[row_key]][r[col_key]] += r[value_key]
    for n in names:
        table[n]["total"] = sum(table[n][c] for c in cols)
    total = {c: sum(table[n][c] for n in names) for c in cols}
    total["total"] = sum(total.values())
    table["total"] = total
    return table


