"""Task: Write `chunked(iterable, size)` that yields lists of up to `size` items from any iterable (lazily: it must work on an infinite generator), `windowed(seq, n, step=1)` that returns overlapping tuples of length n advancing by step (no partial windows), and `dedupe(iterable, key=None)` that yields items in order, skipping ones whose key was seen. size, n and step must be positive (ValueError)."""

from itertools import islice


def chunked(iterable, size):
    if size < 1:
        raise ValueError("size must be positive")
    it = iter(iterable)
    while True:
        batch = list(islice(it, size))
        if not batch:
            return
        yield batch


def windowed(seq, n, step=1):
    if n < 1 or step < 1:
        raise ValueError("n and step must be positive")
    items = list(seq)
    return [tuple(items[i:i + n]) for i in range(0, len(items) - n + 1, step)]


def dedupe(iterable, key=None):
    seen = set()
    for x in iterable:
        k = key(x) if key else x
        if k not in seen:
            seen.add(k)
            yield x


