"""Task: Write `read_typed_csv(text, schema)` that parses CSV text with a header row into a list of dicts, converting columns named in `schema` with the given type name: "int", "float", "bool" (true/false/yes/no/1/0, any case) or "date" (YYYY-MM-DD, to datetime.date). Empty cells become None. Columns not in the schema stay strings. A bad value raises ValueError mentioning the line number (header is line 1) and the column."""

import csv
import datetime
import io

_BOOL = {"true": True, "yes": True, "1": True, "false": False, "no": False, "0": False}


def _convert(kind, raw):
    if kind == "int":
        return int(raw)
    if kind == "float":
        return float(raw)
    if kind == "bool":
        if raw.strip().lower() not in _BOOL:
            raise ValueError(raw)
        return _BOOL[raw.strip().lower()]
    if kind == "date":
        return datetime.date.fromisoformat(raw.strip())
    raise ValueError(f"unknown type {kind}")


def read_typed_csv(text, schema):
    reader = csv.DictReader(io.StringIO(text))
    out = []
    for line_no, row in enumerate(reader, start=2):
        rec = {}
        for col, raw in row.items():
            if raw is None or raw == "":
                rec[col] = None
            elif col in schema:
                try:
                    rec[col] = _convert(schema[col], raw)
                except ValueError:
                    raise ValueError(f"line {line_no}, column {col!r}: bad {schema[col]} {raw!r}") from None
            else:
                rec[col] = raw
        out.append(rec)
    return out


