"""Task: Write `jsonl_stats(lines)` that reads JSON Lines (an iterable of strings) and returns {"records": n, "bad_lines": [line numbers starting at 1], "fields": {field: count of records having it}} for top-level object fields. Blank lines are skipped; lines that are not valid JSON objects are bad."""

import json
from collections import Counter


def jsonl_stats(lines):
    n, bad, fields = 0, [], Counter()
    for i, line in enumerate(lines, 1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            bad.append(i)
            continue
        if not isinstance(obj, dict):
            bad.append(i)
            continue
        n += 1
        fields.update(obj.keys())
    return {"records": n, "bad_lines": bad, "fields": dict(fields)}


