"""Task: Write `statement(opening, transactions)` where transactions are (date string, description, amount) tuples with positive deposits and negative withdrawals. Return a list of dicts in date order (stable for equal dates) with "date", "description", "amount" and "balance" after each one, using Decimal amounts rounded to cents. Also write `overdrafts(rows)` returning the dates on which the balance first went below zero (each dip counted once until it recovers to zero or above)."""

from decimal import ROUND_HALF_UP, Decimal


def _money(x):
    return Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def statement(opening, transactions):
    balance = _money(opening)
    rows = []
    for date, desc, amount in sorted(transactions, key=lambda t: t[0]):
        amt = _money(amount)
        balance += amt
        rows.append({"date": date, "description": desc, "amount": amt, "balance": balance})
    return rows


def overdrafts(rows):
    dates, below = [], False
    for r in rows:
        if r["balance"] < 0 and not below:
            dates.append(r["date"])
            below = True
        elif r["balance"] >= 0:
            below = False
    return dates


