"""Task: Write `settle(expenses)` for splitting group costs: each expense is (payer, amount, participants) and is shared equally by its participants. Return a list of (debtor, creditor, amount) payments, amounts rounded to cents, that settles everyone, using a greedy match of the largest debtor with the largest creditor (names break ties alphabetically). Write `balances(expenses)` too, returning each person's net balance (positive means they are owed)."""

from collections import defaultdict


def balances(expenses):
    net = defaultdict(float)
    for payer, amount, people in expenses:
        share = amount / len(people)
        net[payer] += amount
        for p in people:
            net[p] -= share
    return {k: round(v, 2) for k, v in sorted(net.items())}


def settle(expenses):
    net = balances(expenses)
    debtors = [[-v, k] for k, v in net.items() if v < -0.005]
    creditors = [[v, k] for k, v in net.items() if v > 0.005]
    out = []
    while debtors and creditors:
        debtors.sort(key=lambda x: (-x[0], x[1]))
        creditors.sort(key=lambda x: (-x[0], x[1]))
        d, c = debtors[0], creditors[0]
        pay = round(min(d[0], c[0]), 2)
        out.append((d[1], c[1], pay))
        d[0] = round(d[0] - pay, 2)
        c[0] = round(c[0] - pay, 2)
        if d[0] <= 0.005:
            debtors.pop(0)
        if c[0] <= 0.005:
            creditors.pop(0)
    return out


