        total[d] = total.get(d, 0) - amt
        total[c] = total.get(c, 0) + amt
    expected = {k: v for k, v in balances(exp).items() if v}
    assert set(total) == set(expected)
    assert all(abs(total[k] - expected[k]) <= 0.02 for k in expected)  # cents lost to rounding at most


