"""Task: Write `hours_by_week(entries)` where entries are (date "YYYY-MM-DD", start "HH:MM", end "HH:MM") work periods. A period whose end is earlier than its start runs past midnight and counts for its start date. Return a dict mapping ISO week labels like "2024-W05" to total hours rounded to 2 places, sorted by week. Overlapping periods on the same date are counted once (merge them first). Bad times raise ValueError."""

import datetime


def _minutes(hhmm):
    h, m = hhmm.split(":")
    h, m = int(h), int(m)
    if not (0 <= h < 24 and 0 <= m < 60):
        raise ValueError(f"bad time {hhmm!r}")
    return h * 60 + m


def hours_by_week(entries):
    by_date = {}
    for day, start, end in entries:
        s, e = _minutes(start), _minutes(end)
        if e <= s:
            e += 24 * 60
        by_date.setdefault(day, []).append((s, e))
    weeks = {}
    for day, spans in by_date.items():
        spans.sort()
        total, cur_s, cur_e = 0, None, None
        for s, e in spans:
            if cur_e is None or s > cur_e:
                if cur_e is not None:
                    total += cur_e - cur_s
                cur_s, cur_e = s, e
            else:
                cur_e = max(cur_e, e)
        total += cur_e - cur_s
        y, w, _ = datetime.date.fromisoformat(day).isocalendar()
        label = f"{y}-W{w:02d}"
        weeks[label] = weeks.get(label, 0) + total
    return {k: round(v / 60, 2) for k, v in sorted(weeks.items())}


