"""Task: Write `free_slots(busy, day_start, day_end, min_minutes=30)` that takes busy intervals as ("HH:MM", "HH:MM") pairs (unsorted, possibly overlapping or extending outside the day) and returns the free intervals within [day_start, day_end] that are at least min_minutes long, as "HH:MM" pairs in order."""

def _m(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m


def _t(m):
    return f"{m // 60:02d}:{m % 60:02d}"


def free_slots(busy, day_start, day_end, min_minutes=30):
    start, end = _m(day_start), _m(day_end)
    spans = sorted((max(_m(a), start), min(_m(b), end)) for a, b in busy)
    out, cur = [], start
    for a, b in spans:
        if b <= cur:
            continue
        if a - cur >= min_minutes:
            out.append((_t(cur), _t(a)))
        cur = max(cur, b)
    if end - cur >= min_minutes:
        out.append((_t(cur), _t(end)))
    return out


