"""Task: Write `business_days(start, end, holidays=())` counting weekdays (Mon-Fri) from start to end inclusive, skipping the given holiday dates; if end is before start the count is negative (the same days counted backwards). Write `add_business_days(start, n, holidays=())` that returns the date n business days after start (n may be negative; n = 0 returns start, or the next business day if start is not one). Dates are datetime.date objects."""

import datetime

ONE = datetime.timedelta(days=1)


def _is_bday(d, hol):
    return d.weekday() < 5 and d not in hol


def business_days(start, end, holidays=()):
    hol = set(holidays)
    if end < start:
        return -business_days(end, start, hol)
    n, d = 0, start
    while d <= end:
        n += _is_bday(d, hol)
        d += ONE
    return n


def add_business_days(start, n, holidays=()):
    hol = set(holidays)
    d = start
    if n == 0:
        while not _is_bday(d, hol):
            d += ONE
        return d
    step = ONE if n > 0 else -ONE
    left = abs(n)
    while left:
        d += step
        if _is_bday(d, hol):
            left -= 1
    return d


from datetime import date


