"""Task: Write `resample(points, minutes, how="mean")` that groups (datetime, value) points into consecutive buckets of `minutes` length aligned to midnight, and returns (bucket_start, aggregate) pairs for every bucket from the first to the last point, in order. `how` is "mean", "sum", "max" or "last" (the latest point in time). Empty buckets in between get None. Unsorted input is allowed."""

import datetime


def resample(points, minutes, how="mean"):
    if not points:
        return []
    width = datetime.timedelta(minutes=minutes)

    def floor(t):
        midnight = t.replace(hour=0, minute=0, second=0, microsecond=0)
        return midnight + ((t - midnight) // width) * width

    buckets = {}
    for t, v in sorted(points, key=lambda p: p[0]):
        buckets.setdefault(floor(t), []).append(v)
    agg = {"mean": lambda vs: sum(vs) / len(vs), "sum": sum, "max": max, "last": lambda vs: vs[-1]}[how]
    out, cur, last = [], min(buckets), max(buckets)
    while cur <= last:
        vs = buckets.get(cur)
        out.append((cur, agg(vs) if vs else None))
        cur += width
    return out


