"""Task: Write `fill_dates(rows, fill="previous")` where rows are (date string "YYYY-MM-DD", value) pairs, possibly unsorted and with gaps. Return a sorted list covering every day from the first to the last date. Missing days get the previous known value when fill is "previous", 0 when fill is "zero", or a linear interpolation between neighbours (rounded to 2 places) when fill is "linear". Duplicate dates raise ValueError."""

import datetime


def fill_dates(rows, fill="previous"):
    known = {}
    for d, v in rows:
        day = datetime.date.fromisoformat(d)
        if day in known:
            raise ValueError(f"duplicate date {d}")
        known[day] = v
    if not known:
        return []
    days = sorted(known)
    out = []
    d = days[0]
    while d <= days[-1]:
        if d in known:
            out.append((d.isoformat(), known[d]))
        elif fill == "zero":
            out.append((d.isoformat(), 0))
        elif fill == "previous":
            out.append((d.isoformat(), out[-1][1]))
        elif fill == "linear":
            before = max(k for k in days if k < d)
            after = min(k for k in days if k > d)
            frac = (d - before).days / (after - before).days
            out.append((d.isoformat(), round(known[before] + frac * (known[after] - known[before]), 2)))
        else:
            raise ValueError(f"unknown fill {fill!r}")
        d += datetime.timedelta(days=1)
    return out


