"""Task: Write `load_config(path, defaults=None)` that reads an INI file with configparser and returns a dict of sections, each a dict of options converted to int, float or bool ("true"/"false"/"yes"/"no"/"on"/"off") when they look like one, otherwise strings. `defaults` is a nested dict merged underneath (file values win). A missing file raises FileNotFoundError with the path in the message."""

import configparser
import os
import re

_BOOLS = {"true": True, "yes": True, "on": True, "false": False, "no": False, "off": False}


def _convert(v):
    low = v.strip().lower()
    if low in _BOOLS:
        return _BOOLS[low]
    if re.fullmatch(r"[+-]?\d+", low):
        return int(low)
    if re.fullmatch(r"[+-]?(\d+\.\d*|\.\d+|\d+(\.\d*)?e[+-]?\d+)", low):
        return float(low)
    return v


def load_config(path, defaults=None):
    if not os.path.exists(path):
        raise FileNotFoundError(f"config file not found: {path}")
    parser = configparser.ConfigParser(interpolation=None)
    parser.read(path, encoding="utf-8")
    out = {s: dict(v) for s, v in (defaults or {}).items()}
    for section in parser.sections():
        out.setdefault(section, {})
        for key, value in parser.items(section):
            out[section][key] = _convert(value)
    return out


