"""Task: Write `find_duplicates(root)` that walks a directory tree and returns groups of files with identical contents: a list of lists of paths relative to root (as POSIX strings), each group sorted, groups sorted by their first path. Files are first grouped by size and only same-size files are hashed (SHA-256, read in chunks). Empty files are ignored."""

import hashlib
import os
from collections import defaultdict
from pathlib import Path


def _digest(path, chunk=1 << 16):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            block = f.read(chunk)
            if not block:
                break
            h.update(block)
    return h.hexdigest()


def find_duplicates(root):
    root = Path(root)
    by_size = defaultdict(list)
    for dirpath, _, files in os.walk(root):
        for name in files:
            p = Path(dirpath) / name
            if p.is_file() and not p.is_symlink():
                size = p.stat().st_size
                if size:
                    by_size[size].append(p)
    groups = []
    for paths in by_size.values():
        if len(paths) < 2:
            continue
        by_hash = defaultdict(list)
        for p in paths:
            by_hash[_digest(p)].append(p.relative_to(root).as_posix())
        groups += [sorted(g) for g in by_hash.values() if len(g) > 1]
    return sorted(groups)


def make(tmp_path, files):
    for rel, data in files.items():
        p = tmp_path / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)


def test_groups(tmp_path):
    make(tmp_path, {"a.txt": b"hello", "sub/b.txt": b"hello", "c.txt": b"other", "sub/deep/d.bin": b"other",
                    "e.txt": b"hellp"})
    assert find_duplicates(tmp_path) == [["a.txt", "sub/b.txt"], ["c.txt", "sub/deep/d.bin"]]


