"""Task: Write `plan_renames(directory, pattern, template)` that matches file names in one directory (not recursive) against a regex `pattern` and builds new names from `template` using {name} groups and {n} (1-based counter in sorted order of the original names, zero-padded with {n:03d} style formats). Return a list of (old, new) pairs. Raise ValueError if two files would get the same name or a new name collides with an existing file that is not itself being renamed. Write `apply_renames(directory, plan)` that performs it safely (via temporary names, so swaps work)."""

import os
import re
import uuid


def plan_renames(directory, pattern, template):
    rx = re.compile(pattern)
    names = sorted(n for n in os.listdir(directory) if os.path.isfile(os.path.join(directory, n)))
    plan, n = [], 0
    for name in names:
        m = rx.fullmatch(name)
        if not m:
            continue
        n += 1
        new = template.format(n=n, **m.groupdict())
        if new != name:
            plan.append((name, new))
    targets = [new for _, new in plan]
    if len(set(targets)) != len(targets):
        raise ValueError("two files would get the same name")
    moving = {old for old, _ in plan}
    for t in targets:
        if t in names and t not in moving:
            raise ValueError(f"{t} already exists")
    return plan


def apply_renames(directory, plan):
    tmp = []
    for old, new in plan:
        t = f".rename-{uuid.uuid4().hex}"
        os.rename(os.path.join(directory, old), os.path.join(directory, t))
        tmp.append((t, new))
    for t, new in tmp:
        os.rename(os.path.join(directory, t), os.path.join(directory, new))


import pytest


def touch(d, *names):
    for n in names:
        (d / n).write_text(n)


def test_plan(tmp_path):
    touch(tmp_path, "IMG_9.jpg", "IMG_10.jpg", "notes.txt")
    plan = plan_renames(tmp_path, r"IMG_(?P<num>\d+)\.jpg", "photo-{n:03d}-{num}.jpg")
    assert plan == [("IMG_10.jpg", "photo-001-10.jpg"), ("IMG_9.jpg", "photo-002-9.jpg")]


def test_apply(tmp_path):
    touch(tmp_path, "a.txt", "b.txt")
    plan = plan_renames(tmp_path, r"(?P<stem>\w)\.txt", "{stem}.md")
    apply_renames(tmp_path, plan)
    assert sorted(p.name for p in tmp_path.iterdir()) == ["a.md", "b.md"]
    assert (tmp_path / "a.md").read_text() == "a.txt"


def test_swap(tmp_path):
    touch(tmp_path, "1.txt", "2.txt")
    plan = [("1.txt", "2.txt"), ("2.txt", "1.txt")]
    apply_renames(tmp_path, plan)
    assert (tmp_path / "1.txt").read_text() == "2.txt"


