"""Task: Write `count_lines(root, extensions=(".py",))` that walks a project and returns {"files", "code", "comment", "blank"} totals for files with the given extensions, skipping directories named .git, __pycache__, node_modules and any starting with ".venv" or "venv". A comment line is one whose first non-space character is "#". Lines inside triple-quoted docstrings count as code (keep it simple)."""

import os

SKIP = {".git", "__pycache__", "node_modules"}


def count_lines(root, extensions=(".py",)):
    totals = {"files": 0, "code": 0, "comment": 0, "blank": 0}
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP and not d.startswith((".venv", "venv"))]
        for name in filenames:
            if not name.endswith(tuple(extensions)):
                continue
            totals["files"] += 1
            with open(os.path.join(dirpath, name), encoding="utf-8", errors="replace") as f:
                for line in f:
                    s = line.strip()
                    if not s:
                        totals["blank"] += 1
                    elif s.startswith("#"):
                        totals["comment"] += 1
                    else:
                        totals["code"] += 1
    return totals


def write(p, text):
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text)


