"""Task: Write `log_report(lines)` for log lines like "2024-05-01 12:00:03,123 ERROR [db] connection lost". Return {"levels": count per level, "by_logger": {logger: {level: count}}, "first_error": the timestamp string of the first ERROR or CRITICAL line or None, "unparsed": number of lines that don't match}. Lines that start with whitespace are continuation lines (e.g. tracebacks) and are neither counted nor unparsed."""

import re
from collections import Counter, defaultdict

_LINE = re.compile(r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{3}) (DEBUG|INFO|WARNING|ERROR|CRITICAL) \[([^\]]+)\] ")


def log_report(lines):
    levels = Counter()
    by_logger = defaultdict(Counter)
    first_error, unparsed = None, 0
    for line in lines:
        if not line.strip() or line[0].isspace():
            continue
        m = _LINE.match(line)
        if not m:
            unparsed += 1
            continue
        ts, level, logger = m.groups()
        levels[level] += 1
        by_logger[logger][level] += 1
        if first_error is None and level in ("ERROR", "CRITICAL"):
            first_error = ts
    return {"levels": dict(levels), "by_logger": {k: dict(v) for k, v in by_logger.items()},
            "first_error": first_error, "unparsed": unparsed}


