    out = log_report(["2024-05-01 12:00:00,001 DEBUG [x] hi"])
    assert out["first_error"] is None and out["unparsed"] == 0

"""Task: Write `access_stats(lines)` for web server logs in the Common Log Format, e.g. '127.0.0.1 - frank [10/Oct/2000:13:55:36 -0700] "GET /a.gif HTTP/1.0" 200 2326'. Return {"requests": n, "status": count per status class like "2xx", "top_paths": the 3 most requested paths without query strings as (path, count) with ties alphabetical, "bytes": total bytes (a "-" size counts as 0), "unique_ips": number of distinct client IPs}. Malformed lines are skipped."""

import re
from collections import Counter

_CLF = re.compile(r'^(\S+) \S+ \S+ \[[^\]]+\] "(\S+) (\S+)[^"]*" (\d{3}) (\d+|-)')


def access_stats(lines):
    n, status, paths, total, ips = 0, Counter(), Counter(), 0, set()
    for line in lines:
        m = _CLF.match(line)
        if not m:
            continue
        ip, _, path, code, size = m.groups()
        n += 1
        status[code[0] + "xx"] += 1
        paths[path.split("?", 1)[0]] += 1
        total += 0 if size == "-" else int(size)
        ips.add(ip)
    top = sorted(paths.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
    return {"requests": n, "status": dict(status), "top_paths": top, "bytes": total, "unique_ips": len(ips)}


