"""Task: Write `save_json(path, data)` that writes JSON atomically: dump to a temporary file in the same directory, flush and fsync it, then os.replace it over the target, so a crash never leaves a half-written file; on any error the temporary file is removed and the original file stays untouched. Write `load_json(path, default)` that returns default when the file does not exist."""

import json
import os
import tempfile


def save_json(path, data):
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp = tempfile.mkstemp(prefix=".tmp-", dir=directory)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, sort_keys=True)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, path)
    except BaseException:
        try:
            os.remove(tmp)
        except FileNotFoundError:
            pass
        raise


def load_json(path, default):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        return default


