"""Task: Write `parse_ipv4(text)` returning the address as an int (ValueError for anything that isn't four decimal octets 0-255 without leading zeros), `in_cidr(ip, cidr)` telling whether an address string is inside a block such as "10.0.0.0/8", and `cidr_range(cidr)` returning (first, last) address strings. Do not use the ipaddress module."""

def parse_ipv4(text):
    parts = text.split(".")
    if len(parts) != 4:
        raise ValueError(f"bad address {text!r}")
    n = 0
    for p in parts:
        if not p.isdigit() or (len(p) > 1 and p[0] == "0") or int(p) > 255:
            raise ValueError(f"bad address {text!r}")
        n = n * 256 + int(p)
    return n


def _fmt(n):
    return ".".join(str((n >> s) & 255) for s in (24, 16, 8, 0))


def _block(cidr):
    addr, _, bits = cidr.partition("/")
    if not bits.isdigit() or not 0 <= int(bits) <= 32:
        raise ValueError(f"bad prefix in {cidr!r}")
    mask = (0xFFFFFFFF << (32 - int(bits))) & 0xFFFFFFFF
    return parse_ipv4(addr) & mask, mask


def in_cidr(ip, cidr):
    net, mask = _block(cidr)
    return parse_ipv4(ip) & mask == net


def cidr_range(cidr):
    net, mask = _block(cidr)
    return _fmt(net), _fmt(net | (~mask & 0xFFFFFFFF))


import pytest


