"""Task: Write `check_password(pw, username="")` returning a list of problems (empty when the password is fine): "too short" under 12 characters, "no digit", "no uppercase", "no lowercase", "no symbol" (a character that is not a letter, digit or space), "contains username" (case-insensitive, usernames of 3+ characters), and "repeated characters" when the same character appears 4 times in a row. Problems are listed in that order."""

import re


def check_password(pw, username=""):
    problems = []
    if len(pw) < 12:
        problems.append("too short")
    if not re.search(r"\d", pw):
        problems.append("no digit")
    if not re.search(r"[A-Z]", pw):
        problems.append("no uppercase")
    if not re.search(r"[a-z]", pw):
        problems.append("no lowercase")
    if not re.search(r"[^A-Za-z0-9 ]", pw):
        problems.append("no symbol")
    if len(username) >= 3 and username.lower() in pw.lower():
        problems.append("contains username")
    if re.search(r"(.)\1{3}", pw):
        problems.append("repeated characters")
    return problems


