"""Task: Write `parse_query(qs)` that turns a query string ("a=1&b=two&a=3&flag") into a dict where repeated keys become lists, keys without "=" map to "", and values are percent-decoded with "+" as space. Write `build_url(base, params)` that appends params (dict; list values repeat the key; None values are skipped) to a base URL that may already contain a query string or fragment, keeping the fragment at the end and sorting the new keys."""

from urllib.parse import quote_plus, unquote_plus


def parse_query(qs):
    out = {}
    for part in qs.lstrip("?").split("&"):
        if not part:
            continue
        key, _, value = part.partition("=")
        key, value = unquote_plus(key), unquote_plus(value)
        if key in out:
            if not isinstance(out[key], list):
                out[key] = [out[key]]
            out[key].append(value)
        else:
            out[key] = value
    return out


def build_url(base, params):
    base, hash_, frag = base.partition("#")
    pairs = []
    for k in sorted(params):
        v = params[k]
        if v is None:
            continue
        for item in v if isinstance(v, list) else [v]:
            pairs.append(f"{quote_plus(str(k))}={quote_plus(str(item))}")
    if pairs:
        sep = "&" if "?" in base else "?"
        if base.endswith(("?", "&")):
            sep = ""
        base += sep + "&".join(pairs)
    return base + (hash_ + frag if hash_ else "")


def test_parse():
    assert parse_query("a=1&b=two&a=3&flag") == {"a": ["1", "3"], "b": "two", "flag": ""}


def test_decode():
    assert parse_query("?q=hello+world&x=%2Fpath%3F") == {"q": "hello world", "x": "/path?"}


def test_build():
    assert build_url("https://x.org/s", {"q": "a b", "page": 2}) == "https://x.org/s?page=2&q=a+b"


def test_build_existing_query_and_fragment():
    url = build_url("https://x.org/s?lang=en#top", {"tag": ["py", "web"], "skip": None})
    assert url == "https://x.org/s?lang=en&tag=py&tag=web#top"


def test_build_empty():
    assert build_url("https://x.org/", {}) == "https://x.org/"

"""Task: Write `parse_cookie(header)` that reads a Cookie request header ("a=1; b=hello%20world; c") into a dict (percent-decoded values, double quotes around values removed, entries without "=" skipped, first occurrence wins). Write `set_cookie(name, value, max_age=None, path="/", secure=True, http_only=True, same_site="Lax")` returning a Set-Cookie header value with attributes in that order; same_site must be Strict, Lax or None, and None requires secure (ValueError otherwise)."""

from urllib.parse import quote, unquote


def parse_cookie(header):
    out = {}
    for part in header.split(";"):
        if "=" not in part:
            continue
        k, v = part.split("=", 1)
        k, v = k.strip(), v.strip()
        if len(v) >= 2 and v[0] == v[-1] == '"':
            v = v[1:-1]
        if k and k not in out:
            out[k] = unquote(v)
    return out


def set_cookie(name, value, max_age=None, path="/", secure=True, http_only=True, same_site="Lax"):
    if same_site not in ("Strict", "Lax", "None"):
        raise ValueError("same_site must be Strict, Lax or None")
    if same_site == "None" and not secure:
        raise ValueError("SameSite=None requires Secure")
    parts = [f"{name}={quote(str(value), safe='')}"]
    if max_age is not None:
        parts.append(f"Max-Age={int(max_age)}")
    if path:
        parts.append(f"Path={path}")
    if secure:
        parts.append("Secure")
    if http_only:
        parts.append("HttpOnly")
    parts.append(f"SameSite={same_site}")
    return "; ".join(parts)


