"""Task: Write `isbn_valid(text)` that accepts ISBN-10 (last character may be "X") and ISBN-13 numbers, ignoring hyphens and spaces, and checks the check digit. Write `isbn10_to_13(text)` converting a valid ISBN-10 to ISBN-13 (prefix 978, new check digit), raising ValueError for invalid input."""

def _clean(text):
    return text.replace("-", "").replace(" ", "").upper()


def _valid10(s):
    if len(s) != 10 or not s[:9].isdigit() or not (s[9].isdigit() or s[9] == "X"):
        return False
    total = sum((10 - i) * int(c) for i, c in enumerate(s[:9])) + (10 if s[9] == "X" else int(s[9]))
    return total % 11 == 0


def _check13(first12):
    total = sum(int(c) * (1 if i % 2 == 0 else 3) for i, c in enumerate(first12))
    return str((10 - total % 10) % 10)


def isbn_valid(text):
    s = _clean(text)
    if len(s) == 10:
        return _valid10(s)
    return len(s) == 13 and s.isdigit() and _check13(s[:12]) == s[12]


def isbn10_to_13(text):
    s = _clean(text)
    if not _valid10(s):
        raise ValueError(f"invalid ISBN-10 {text!r}")
    body = "978" + s[:9]
    return body + _check13(body)


