"""Task: Write `iban_valid(text)` that validates an IBAN: ignore spaces, uppercase it, require 15 to 34 letters and digits starting with a two-letter country code and two digits, move the first four characters to the end, replace letters with numbers (A=10 ... Z=35) and check the result mod 97 is 1. Write `format_iban(text)` returning it uppercase in groups of four separated by spaces, or raising ValueError if invalid."""

import re


def _clean(text):
    return text.replace(" ", "").upper()


def iban_valid(text):
    s = _clean(text)
    if not re.fullmatch(r"[A-Z]{2}\d{2}[A-Z0-9]{11,30}", s):
        return False
    moved = s[4:] + s[:4]
    digits = "".join(str(int(c, 36)) for c in moved)
    return int(digits) % 97 == 1


def format_iban(text):
    if not iban_valid(text):
        raise ValueError("invalid IBAN")
    s = _clean(text)
    return " ".join(s[i:i + 4] for i in range(0, len(s), 4))


