"""Task: Write `parse_headers(raw)` that parses an HTTP/1.1 response head (status line, then header lines, ending at a blank line) into (status_code, reason, headers) where headers is a dict with lowercase names; repeated headers are joined with ", " except Set-Cookie, which becomes a list. Obsolete folded continuation lines (starting with a space or tab) are appended to the previous header with one space. A malformed status line raises ValueError."""

import re


def parse_headers(raw):
    lines = raw.replace("\r\n", "\n").split("\n")
    m = re.fullmatch(r"HTTP/\d\.\d (\d{3})(?: (.*))?", lines[0].strip())
    if not m:
        raise ValueError(f"bad status line {lines[0]!r}")
    headers, last = {}, None
    for line in lines[1:]:
        if not line.strip():
            break
        if line[0] in " \t" and last:
            if isinstance(headers[last], list):
                headers[last][-1] += " " + line.strip()
            else:
                headers[last] += " " + line.strip()
            continue
        name, _, value = line.partition(":")
        name, value = name.strip().lower(), value.strip()
        if name == "set-cookie":
            headers.setdefault(name, []).append(value)
        elif name in headers:
            headers[name] += ", " + value
        else:
            headers[name] = value
        last = name
    return int(m.group(1)), m.group(2) or "", headers


