"""Task: Write `line_diff(a, b)` returning a unified-style list of lines comparing two lists of strings: unchanged lines prefixed " ", removed "- ", added "+ ", computed from a longest common subsequence (when several are possible, prefer showing removals before additions). Write `diff_stats(diff)` returning (added, removed) counts."""

def line_diff(a, b):
    n, m = len(a), len(b)
    lcs = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            lcs[i][j] = lcs[i + 1][j + 1] + 1 if a[i] == b[j] else max(lcs[i + 1][j], lcs[i][j + 1])
    out, i, j = [], 0, 0
    while i < n and j < m:
        if a[i] == b[j]:
            out.append("  " + a[i])
            i += 1
            j += 1
        elif lcs[i + 1][j] >= lcs[i][j + 1]:
            out.append("- " + a[i])
            i += 1
        else:
            out.append("+ " + b[j])
            j += 1
    out += ["- " + x for x in a[i:]] + ["+ " + x for x in b[j:]]
    return out


def diff_stats(diff):
    return sum(d.startswith("+ ") for d in diff), sum(d.startswith("- ") for d in diff)


def test_change():
    assert line_diff(["a", "b", "c"], ["a", "x", "c"]) == ["  a", "- b", "+ x", "  c"]


def test_insert_delete():
    assert line_diff(["a", "c"], ["a", "b", "c", "d"]) == ["  a", "+ b", "  c", "+ d"]
    assert line_diff(["a", "b"], []) == ["- a", "- b"]


def test_identical():
    assert line_diff(["x"], ["x"]) == ["  x"]


def test_stats():
