    assert [x for x in d if x.startswith("  ")] in (["  1", "  3", "  4"], ["  1", "  2", "  4"])

"""Task: Write `merge_intervals(intervals)` that merges overlapping or touching closed integer intervals [start, end] given as pairs (start <= end, else ValueError) and returns them sorted. Write `subtract(intervals, cut)` returning the parts of the merged intervals not covered by the interval `cut` (integers, so removing [3, 5] from [1, 10] leaves [1, 2] and [6, 10])."""

def merge_intervals(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError(f"bad interval {(s, e)}")
    out = []
    for s, e in sorted(intervals):
        if out and s <= out[-1][1] + 1:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return [tuple(x) for x in out]


def subtract(intervals, cut):
    cs, ce = cut
    out = []
    for s, e in merge_intervals(intervals):
        if e < cs or s > ce:
            out.append((s, e))
            continue
        if s < cs:
            out.append((s, cs - 1))
        if e > ce:
            out.append((ce + 1, e))
    return out


import pytest


