    assert subtract([(1, 4)], (0, 10)) == []

"""Task: Write `alerts(values, window, high, low)` that computes a simple moving average over the last `window` values (only once the window is full) and returns a list of (index, "high") / (index, "low") events: "high" when the average rises above `high` while not already in the high state, and a return to normal only happens when it drops below `low` (hysteresis). Index is the position of the value that completed the window. low must be below high (ValueError)."""

from collections import deque


def alerts(values, window, high, low):
    if low >= high:
        raise ValueError("low must be below high")
    if window < 1:
        raise ValueError("window must be positive")
    buf, total, state, out = deque(), 0.0, "normal", []
    for i, v in enumerate(values):
        buf.append(v)
        total += v
        if len(buf) > window:
            total -= buf.popleft()
        if len(buf) < window:
            continue
        avg = total / window
        if state == "normal" and avg > high:
            state = "high"
            out.append((i, "high"))
        elif state == "high" and avg < low:
            state = "normal"
            out.append((i, "low"))
    return out


import pytest


