"""Task: Write `debounce(events, wait)` where events are (timestamp_seconds, name) pairs sorted by time: for each name, a burst of events with gaps smaller than `wait` collapses into one, emitted at the time of the last event in the burst plus `wait`. Return (emit_time, name, count) tuples sorted by emit time, then name. Write `throttle(events, interval)` that keeps, per name, only events at least `interval` seconds after the last kept one."""

def debounce(events, wait):
    open_bursts, out = {}, []
    for t, name in events:
        if name in open_bursts and t - open_bursts[name][0] < wait:
            last, n = open_bursts[name]
            open_bursts[name] = (t, n + 1)
        else:
            if name in open_bursts:
                last, n = open_bursts[name]
                out.append((last + wait, name, n))
            open_bursts[name] = (t, 1)
    for name, (last, n) in open_bursts.items():
        out.append((last + wait, name, n))
    return sorted(out, key=lambda x: (x[0], x[1]))


def throttle(events, interval):
    last, out = {}, []
    for t, name in events:
        if name not in last or t - last[name] >= interval:
            last[name] = t
            out.append((t, name))
    return out


EV = [(0.0, "save"), (0.2, "save"), (0.3, "resize"), (0.5, "save"), (2.0, "save"), (2.1, "resize")]


def test_debounce():
    assert debounce(EV, 1.0) == [(1.3, "resize", 1), (1.5, "save", 3), (3.0, "save", 1), (3.1, "resize", 1)]


def test_debounce_single():
    assert debounce([(5, "x")], 2) == [(7, "x", 1)]


def test_gap_equal_to_wait_splits():
    assert debounce([(0, "a"), (1, "a")], 1) == [(1, "a", 1), (2, "a", 1)]


def test_throttle():
    assert throttle(EV, 1.0) == [(0.0, "save"), (0.3, "resize"), (2.0, "save"), (2.1, "resize")]


def test_empty():
    assert debounce([], 1) == [] and throttle([], 1) == []

"""Task: Write `cron_matches(expr, when)` for five-field cron expressions (minute hour day-of-month month day-of-week, Sunday = 0 or 7) supporting "*", numbers, ranges "1-5", lists "1,15", and steps "*/15" or "10-30/10". Follow cron's rule: if both day fields are restricted, a match on either is enough. Write `next_run(expr, after)` returning the first matching minute strictly after `after` (search up to 366 days, else ValueError). Bad fields raise ValueError."""

import datetime

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _field(text, lo, hi):
    values = set()
    for part in text.split(","):
        rng, _, step = part.partition("/")
        step = int(step) if step else 1
        if step < 1:
            raise ValueError("bad step")
        if rng == "*":
            a, b = lo, hi
        elif "-" in rng:
            a, b = map(int, rng.split("-"))
        else:
            a = b = int(rng)
        if not (lo <= a <= b <= hi):
            raise ValueError(f"value out of range in {text!r}")
        values.update(range(a, b + 1, step))
    return values


def _parse(expr):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("need five fields")
    try:
        sets = [_field(f, lo, hi) for f, (lo, hi) in zip(fields, RANGES)]
    except ValueError as e:
        raise ValueError(f"bad cron expression {expr!r}: {e}") from None
    if 7 in sets[4]:
        sets[4].add(0)
    return sets, fields


def cron_matches(expr, when):
    (mins, hours, dom, months, dow), fields = _parse(expr)
    if when.minute not in mins or when.hour not in hours or when.month not in months:
        return False
    day_ok = when.day in dom
    wd = (when.weekday() + 1) % 7
    week_ok = wd in dow
    if fields[2] != "*" and fields[4] != "*":
        return day_ok or week_ok
    return day_ok and week_ok


def next_run(expr, after):
    _parse(expr)
    t = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
    end = after + datetime.timedelta(days=366)
    while t <= end:
        if cron_matches(expr, t):
            return t
        t += datetime.timedelta(minutes=1)
    raise ValueError("no run within a year")


from datetime import datetime as dt

import pytest


def test_basic():
    assert cron_matches("*/15 9-17 * * 1-5", dt(2024, 5, 6, 9, 30))
    assert not cron_matches("*/15 9-17 * * 1-5", dt(2024, 5, 5, 9, 30))
    assert not cron_matches("*/15 9-17 * * 1-5", dt(2024, 5, 6, 9, 31))


def test_lists_and_sunday_seven():
    assert cron_matches("0 0 * * 7", dt(2024, 5, 5, 0, 0))
    assert cron_matches("5,35 * * * *", dt(2024, 1, 1, 3, 35))


def test_day_fields_or():
    assert cron_matches("0 12 1 * 1", dt(2024, 5, 6, 12, 0))
    assert cron_matches("0 12 1 * 1", dt(2024, 6, 1, 12, 0))


def test_next_run():
    assert next_run("30 2 * * *", dt(2024, 5, 6, 2, 30)) == dt(2024, 5, 7, 2, 30)
    with pytest.raises(ValueError):
        next_run("0 0 29 2 *", dt(2024, 3, 1))


def test_bad():
    with pytest.raises(ValueError):
        cron_matches("60 * * * *", dt(2024, 1, 1))
    with pytest.raises(ValueError):
        cron_matches("* * *", dt(2024, 1, 1))

"""Task: Write a class `TopK(k)` that keeps the k largest numbers seen so far from a stream using a min-heap: `add(x)`, `items()` returning them sorted largest first, and `threshold()` returning the smallest value that is currently kept (None until k items were seen). Write `top_k_by(records, k, key)` returning the k records with the largest key value, ties kept in input order."""

import heapq


class TopK:
    def __init__(self, k):
        if k < 1:
            raise ValueError("k must be positive")
        self.k = k
        self.heap = []

    def add(self, x):
        if len(self.heap) < self.k:
            heapq.heappush(self.heap, x)
        elif x > self.heap[0]:
            heapq.heapreplace(self.heap, x)

    def items(self):
        return sorted(self.heap, reverse=True)

    def threshold(self):
        return self.heap[0] if len(self.heap) == self.k else None


def top_k_by(records, k, key):
    indexed = [(key(r), -i, r) for i, r in enumerate(records)]
    best = heapq.nlargest(k, indexed, key=lambda t: (t[0], t[1]))
    return [r for _, _, r in best]


import pytest


def test_topk():
    t = TopK(3)
    for x in [5, 1, 9, 3, 7, 2]:
        t.add(x)
    assert t.items() == [9, 7, 5]
    assert t.threshold() == 5


def test_threshold_before_full():
    t = TopK(2)
    t.add(1)
    assert t.threshold() is None


def test_duplicates():
    t = TopK(2)
    for x in [4, 4, 4]:
        t.add(x)
    assert t.items() == [4, 4]


def test_by_key_ties_in_order():
    recs = [{"n": "a", "s": 5}, {"n": "b", "s": 9}, {"n": "c", "s": 5}, {"n": "d", "s": 1}]
    assert [r["n"] for r in top_k_by(recs, 3, key=lambda r: r["s"])] == ["b", "a", "c"]


def test_bad_k():
    with pytest.raises(ValueError):
        TopK(0)

"""Task: Write `polygon_area(points)` (shoelace formula, absolute value, ValueError for fewer than 3 points), `perimeter(points)` for the closed polygon, `centroid(points)` of a non-degenerate polygon, and `point_in_polygon(pt, points)` using ray casting, where points on an edge count as inside."""

import math


def polygon_area(points):
    if len(points) < 3:
        raise ValueError("need at least 3 points")
    s = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:] + points[:1]):
        s += x1 * y2 - x2 * y1
    return abs(s) / 2


def perimeter(points):
    return sum(math.dist(a, b) for a, b in zip(points, points[1:] + points[:1]))


def centroid(points):
    a = 0.0
    cx = cy = 0.0
    for (x1, y1), (x2, y2) in zip(points, points[1:] + points[:1]):
        cross = x1 * y2 - x2 * y1
        a += cross
        cx += (x1 + x2) * cross
        cy += (y1 + y2) * cross
    if a == 0:
        raise ValueError("degenerate polygon")
    a /= 2
    return cx / (6 * a), cy / (6 * a)


def _on_segment(p, a, b):
    (px, py), (ax, ay), (bx, by) = p, a, b
    cross = (bx - ax) * (py - ay) - (by - ay) * (px - ax)
    return abs(cross) < 1e-9 and min(ax, bx) - 1e-9 <= px <= max(ax, bx) + 1e-9 and min(ay, by) - 1e-9 <= py <= max(ay, by) + 1e-9


def point_in_polygon(pt, points):
    x, y = pt
    inside = False
    for a, b in zip(points, points[1:] + points[:1]):
        if _on_segment(pt, a, b):
            return True
        (x1, y1), (x2, y2) = a, b
        if (y1 > y) != (y2 > y):
            xin = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
            if x < xin:
                inside = not inside
    return inside


import pytest

SQUARE = [(0, 0), (4, 0), (4, 4), (0, 4)]
L_SHAPE = [(0, 0), (2, 0), (2, 1), (1, 1), (1, 2), (0, 2)]


def test_area():
    assert polygon_area(SQUARE) == 16
    assert polygon_area(L_SHAPE) == 3
    assert polygon_area(list(reversed(SQUARE))) == 16


def test_perimeter():
    assert perimeter(SQUARE) == 16


def test_centroid():
    assert centroid(SQUARE) == (2, 2)


def test_point_in():
    assert point_in_polygon((1, 1), SQUARE)
    assert not point_in_polygon((5, 1), SQUARE)
    assert point_in_polygon((4, 2), SQUARE)
    assert not point_in_polygon((1.5, 1.5), L_SHAPE)


