    with pytest.raises(ValueError):
        polygon_area([(0, 0), (1, 1)])
    with pytest.raises(ValueError):
        centroid([(0, 0), (1, 1), (2, 2)])

"""Task: Write `haversine_km(a, b)` for (lat, lon) degree pairs on a sphere of radius 6371 km, and `nearby(origin, places, radius_km)` returning (name, distance rounded to 1 decimal) for places (dict name -> (lat, lon)) within the radius, nearest first, ties by name. Latitudes outside [-90, 90] or longitudes outside [-180, 180] raise ValueError."""

import math

R = 6371.0


def _check(p):
    lat, lon = p
    if not -90 <= lat <= 90 or not -180 <= lon <= 180:
        raise ValueError(f"bad coordinate {p}")


def haversine_km(a, b):
    _check(a)
    _check(b)
    lat1, lon1, lat2, lon2 = map(math.radians, (*a, *b))
    h = math.sin((lat2 - lat1) / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2
    return 2 * R * math.asin(math.sqrt(h))


def nearby(origin, places, radius_km):
    rows = []
    for name, p in places.items():
        d = haversine_km(origin, p)
        if d <= radius_km:
            rows.append((round(d, 1), name))
    return [(name, d) for d, name in sorted(rows)]


import pytest

PARIS, LONDON, BERLIN = (48.8566, 2.3522), (51.5074, -0.1278), (52.52, 13.405)


def test_distance():
    assert round(haversine_km(PARIS, LONDON)) == 344
