"""Task: Write `evaluate(expr)` for arithmetic expressions with integers and decimals, + - * /, unary minus, ^ for power (right-associative, binding tighter than unary minus, so -2^2 = -4) and parentheses, without using eval. Division by zero raises ZeroDivisionError; any syntax error raises ValueError with the position of the bad token. Return an int when the result is a whole number, else a float."""

import re

_TOKEN = re.compile(r"\s*(?:(\d+\.\d*|\.\d+|\d+)|(\S))")


def _tokens(expr):
    out = []
    for m in _TOKEN.finditer(expr):
        if m.group(1):
            out.append(("num", float(m.group(1)), m.start(1)))
        elif m.group(2):
            if m.group(2) not in "+-*/^()":
                raise ValueError(f"unexpected {m.group(2)!r} at {m.start(2)}")
            out.append(("op", m.group(2), m.start(2)))
    out.append(("end", None, len(expr)))
    return out


def evaluate(expr):
    toks = _tokens(expr)
    pos = 0

    def peek():
        return toks[pos]

    def take():
        nonlocal pos
        pos += 1
        return toks[pos - 1]

    def expect(op):
        t = take()
        if t[1] != op:
            raise ValueError(f"expected {op!r} at {t[2]}")

    def atom():
        t = take()
        if t[0] == "num":
            return t[1]
        if t[1] == "(":
            v = add()
            expect(")")
            return v
        raise ValueError(f"unexpected token at {t[2]}")

    def power():
        base = atom()
        if peek()[1] == "^":
            take()
            return base ** unary()
        return base

    def unary():
        if peek()[1] == "-":
            take()
            return -unary()
        if peek()[1] == "+":
            take()
            return unary()
        return power()

    def mul():
        v = unary()
        while peek()[1] in ("*", "/"):
            op = take()[1]
            r = unary()
            if op == "/":
                if r == 0:
                    raise ZeroDivisionError("division by zero")
                v /= r
            else:
                v *= r
        return v

    def add():
        v = mul()
        while peek()[1] in ("+", "-"):
            op = take()[1]
            r = mul()
            v = v + r if op == "+" else v - r
        return v

    result = add()
    if peek()[0] != "end":
        raise ValueError(f"unexpected token at {peek()[2]}")
    return int(result) if float(result).is_integer() else result


import pytest


def test_precedence():
    assert evaluate("1 + 2 * 3") == 7
    assert evaluate("(1 + 2) * 3") == 9
    assert evaluate("2 ^ 3 ^ 2") == 512


def test_unary():
    assert evaluate("-2^2") == -4
    assert evaluate("(-2)^2") == 4
    assert evaluate("3 - -1") == 4


