    assert evaluate("  42 ") == 42

"""Task: Write `backoff_delays(attempts, base=0.5, factor=2, cap=30, jitter=0.1, seed=None)` returning the list of waits before each retry: base * factor**i capped at cap, each multiplied by a random factor in [1 - jitter, 1 + jitter] from random.Random(seed), rounded to 3 places. Write `call_with_retries(fn, attempts, delays, retry_on=(Exception,), sleep=time.sleep)` that calls fn until it succeeds, sleeping the given delays between tries, re-raising the last exception when attempts run out; exceptions not in retry_on propagate at once."""

import random
import time


def backoff_delays(attempts, base=0.5, factor=2, cap=30, jitter=0.1, seed=None):
    rng = random.Random(seed)
    out = []
    for i in range(attempts):
        d = min(cap, base * factor**i)
        d *= rng.uniform(1 - jitter, 1 + jitter)
        out.append(round(d, 3))
    return out


def call_with_retries(fn, attempts, delays, retry_on=(Exception,), sleep=time.sleep):
    if attempts < 1:
        raise ValueError("attempts must be positive")
    for i in range(attempts):
        try:
            return fn()
        except retry_on:
            if i == attempts - 1:
                raise
            sleep(delays[min(i, len(delays) - 1)])


