    assert backoff_delays(8, jitter=0)[-1] == 30


def test_jitter_bounds_and_seed():
    a = backoff_delays(4, seed=1)
    assert a == backoff_delays(4, seed=1)
    assert all(0.9 * x <= y <= 1.1 * x for x, y in zip([0.5, 1, 2, 4], a))


