"""Task: Write `human_bytes(n)` that formats a byte count with binary units: "512 B", "1.0 KiB", "1.5 MiB", up to "TiB", with one decimal place above bytes. Negative numbers raise ValueError. Also write `parse_bytes(text)` that reads strings like "10 KiB", "2.5MiB", "7 B" or "300" (bytes) back into an int, rounding down."""

UNITS = ["B", "KiB", "MiB", "GiB", "TiB"]


def human_bytes(n):
    if n < 0:
        raise ValueError("negative size")
    if n < 1024:
        return f"{n} B"
    value = float(n)
    for unit in UNITS[1:]:
        value /= 1024
        if value < 1024 or unit == UNITS[-1]:
            return f"{value:.1f} {unit}"


def parse_bytes(text):
    text = text.strip()
    for i, unit in reversed(list(enumerate(UNITS))):
        if text.endswith(unit):
            number = text[: -len(unit)].strip()
            return int(float(number) * 1024**i)
    return int(text)


