"""Task: Write `parse_duration(text)` that converts strings such as "1h30m", "45s", "2d 4h", "1h 5m 10s" or "90" (plain seconds) into a number of seconds (int). Units are d, h, m and s; each may appear at most once and in that order. Anything else raises ValueError."""

import re

_PART = re.compile(r"\s*(\d+)\s*([dhms])")
_ORDER = "dhms"
_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}


def parse_duration(text):
    text = text.strip()
    if text.isdigit():
        return int(text)
    pos, total, last = 0, 0, -1
    if not text:
        raise ValueError("empty duration")
    while pos < len(text):
        m = _PART.match(text, pos)
        if not m:
            raise ValueError(f"bad duration: {text!r}")
        idx = _ORDER.index(m.group(2))
        if idx <= last:
            raise ValueError(f"units out of order or repeated: {text!r}")
        last = idx
        total += int(m.group(1)) * _SECONDS[m.group(2)]
        pos = m.end()
    return total


import pytest


