"""Task: Write `wrap(text, width)` that re-wraps text into lines of at most `width` characters, keeping paragraphs (separated by blank lines) apart with a single blank line. Words longer than `width` go on their own line unbroken. Return the result as one string without a trailing newline."""

def wrap(text, width):
    if width < 1:
        raise ValueError("width must be positive")
    paragraphs = [p.split() for p in text.replace("\r\n", "\n").split("\n\n")]
    out = []
    for words in paragraphs:
        if not words:
            continue
        lines, line = [], ""
        for w in words:
            if not line:
                line = w
            elif len(line) + 1 + len(w) <= width:
                line += " " + w
            else:
                lines.append(line)
                line = w
        lines.append(line)
        out.append("\n".join(lines))
    return "\n\n".join(out)


