"""Task: Write `luhn_valid(number)` that checks a card number with the Luhn algorithm (spaces and dashes allowed, at least 12 digits, otherwise False), and `mask_card(number)` that returns the digits with all but the last four replaced by "*", grouped in fours from the left with spaces, e.g. "**** **** **** 1111". mask_card raises ValueError for an invalid number."""

def _digits(number):
    return number.replace(" ", "").replace("-", "")


def luhn_valid(number):
    d = _digits(number)
    if not d.isdigit() or len(d) < 12:
        return False
    total = 0
    for i, ch in enumerate(reversed(d)):
        n = int(ch)
        if i % 2 == 1:
            n *= 2
            if n > 9:
                n -= 9
        total += n
    return total % 10 == 0


def mask_card(number):
    if not luhn_valid(number):
        raise ValueError("invalid card number")
    d = _digits(number)
    masked = "*" * (len(d) - 4) + d[-4:]
    return " ".join(masked[i:i + 4] for i in range(0, len(masked), 4))


import pytest


