"""Task: Write `extract(post)` that returns a dict with three lists, in order of first appearance and without duplicates: "hashtags" (words after "#", lowercased), "mentions" (names after "@", made of letters, digits and underscores) and "urls" (http or https URLs up to the next whitespace, with trailing punctuation .,!?) removed). An email address such as a@b.com is not a mention."""

import re

_URL = re.compile(r"https?://\S+")
_TAG = re.compile(r"(?<![\w&])#(\w+)")
_MENTION = re.compile(r"(?<![\w.])@(\w+)")


def _unique(items):
    seen, out = set(), []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out


def extract(post):
    urls = [u.rstrip(".,!?)") for u in _URL.findall(post)]
    rest = _URL.sub(" ", post)
    return {
        "hashtags": _unique(t.lower() for t in _TAG.findall(rest)),
        "mentions": _unique(_MENTION.findall(rest)),
        "urls": _unique(urls),
    }


