"""Task: Write `rle_encode(s)` that run-length encodes a string as count+char pairs ("aaab" -> "3a1b") and `rle_decode(s)` that reverses it (counts may have several digits). Decoding malformed input (a missing count or a trailing count) raises ValueError. The input strings to encode contain no digits."""

import re


def rle_encode(s):
    if not s:
        return ""
    out, prev, count = [], s[0], 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            out.append(f"{count}{prev}")
            prev, count = ch, 1
    out.append(f"{count}{prev}")
    return "".join(out)


def rle_decode(s):
    if not re.fullmatch(r"(\d+\D)*", s):
        raise ValueError(f"malformed run-length string: {s!r}")
    return "".join(ch * int(n) for n, ch in re.findall(r"(\d+)(\D)", s))


