"""Task: Write `caesar(text, shift)` that shifts letters by `shift` positions (wrapping, keeping case, leaving other characters alone; negative shifts decode) and `vigenere(text, key, decrypt=False)` that applies a Vigenere cipher with an alphabetic key, advancing the key only on letters. An empty or non-alphabetic key raises ValueError."""

def _shift(ch, k):
    if ch.isupper():
        return chr((ord(ch) - 65 + k) % 26 + 65)
    if ch.islower():
        return chr((ord(ch) - 97 + k) % 26 + 97)
    return ch


def caesar(text, shift):
    return "".join(_shift(ch, shift) for ch in text)


def vigenere(text, key, decrypt=False):
    if not key or not key.isalpha():
        raise ValueError("key must be letters")
    shifts = [ord(c) - 97 for c in key.lower()]
    out, i = [], 0
    for ch in text:
        if ch.isalpha() and ch.isascii():
            k = shifts[i % len(shifts)]
            out.append(_shift(ch, -k if decrypt else k))
            i += 1
        else:
            out.append(ch)
    return "".join(out)


import pytest


