"""Task: Write `check_brackets(text)` that returns None when every (), [] and {} in the text is balanced, or the 0-based index of the first offending character otherwise: an unexpected closer, or for an unclosed opener, the index of the earliest one still open at the end. Brackets inside single or double quoted strings are ignored (quotes do not nest; a backslash escapes the next character inside a string)."""

PAIRS = {")": "(", "]": "[", "}": "{"}


def check_brackets(text):
    stack = []
    quote = None
    i = 0
    while i < len(text):
        ch = text[i]
        if quote:
            if ch == "\\":
                i += 2
                continue
            if ch == quote:
                quote = None
        elif ch in "'\"":
            quote = ch
        elif ch in "([{":
            stack.append((ch, i))
        elif ch in PAIRS:
            if not stack or stack[-1][0] != PAIRS[ch]:
                return i
            stack.pop()
        i += 1
    return stack[0][1] if stack else None


def test_balanced():
    assert check_brackets("f(a[1], {b: (2)})") is None
    assert check_brackets("") is None


def test_unexpected_closer():
    assert check_brackets("(a]") == 2
    assert check_brackets("x)") == 1


def test_unclosed():
    assert check_brackets("a(b[c]") == 1
    assert check_brackets("{[") == 0


def test_strings_ignored():
    assert check_brackets("print(')')") is None
    assert check_brackets('s = "\\" ]"') is None


def test_mismatch_inside():
    assert check_brackets("{(})") == 2

"""Task: Write `edit_distance(a, b)` (Levenshtein: insertions, deletions, substitutions cost 1) and `suggest(word, vocabulary, max_distance=2, limit=3)` that returns up to `limit` vocabulary words within `max_distance` of `word` (case-insensitive), closest first, ties alphabetical. An exact match returns just that word."""

def edit_distance(a, b):
    if len(a) < len(b):
        a, b = b, a
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]


def suggest(word, vocabulary, max_distance=2, limit=3):
    w = word.lower()
    scored = []
    for v in vocabulary:
        d = edit_distance(w, v.lower())
        if d == 0:
            return [v]
        if d <= max_distance:
            scored.append((d, v.lower(), v))
    return [v for _, _, v in sorted(scored)[:limit]]


def test_distance():
    assert edit_distance("kitten", "sitting") == 3
    assert edit_distance("", "abc") == 3
    assert edit_distance("same", "same") == 0


def test_symmetry():
    assert edit_distance("flaw", "lawn") == edit_distance("lawn", "flaw") == 2


def test_suggest():
    vocab = ["apple", "apply", "ample", "maple", "angle"]
    assert suggest("appel", vocab) == ["apple", "apply"]
    assert suggest("appel", vocab, max_distance=3, limit=4) == ["apple", "apply", "ample", "maple"]


def test_exact():
    assert suggest("Apple", ["apple", "apply"]) == ["apple"]


def test_nothing_close():
    assert suggest("zzz", ["apple"]) == []

"""Task: Write `toc(markdown)` that builds a table of contents from ATX headings ("#" to "###") as nested bullet lines: two spaces of indent per level below the top level found, each item a link "[Title](#slug)". The slug is lowercase, with spaces turned into "-" and characters other than letters, digits, "-" and "_" removed; repeated slugs get "-1", "-2" suffixes. Headings inside ``` fenced code blocks are ignored."""

import re


def _slug(title):
    s = re.sub(r"[^\w\- ]", "", title.strip().lower())
    return s.replace(" ", "-")


def toc(markdown):
    lines, in_code, seen = [], False, {}
    heads = []
    for line in markdown.splitlines():
        if line.lstrip().startswith("```"):
            in_code = not in_code
            continue
        m = re.match(r"^(#{1,3})\s+(.+?)\s*#*\s*$", line)
        if m and not in_code:
            heads.append((len(m.group(1)), m.group(2)))
    if not heads:
        return ""
    top = min(level for level, _ in heads)
    for level, title in heads:
        slug = _slug(title)
        n = seen.get(slug, 0)
        seen[slug] = n + 1
        if n:
            slug = f"{slug}-{n}"
        lines.append("  " * (level - top) + f"- [{title}](#{slug})")
    return "\n".join(lines)


def test_nested():
    md = "# Intro\ntext\n## Install it\n### On Linux\n## Usage"
    assert toc(md) == ("- [Intro](#intro)\n  - [Install it](#install-it)\n    - [On Linux](#on-linux)\n"
                       "  - [Usage](#usage)")


def test_top_level_is_relative():
    assert toc("## A\n### B") == "- [A](#a)\n  - [B](#b)"


def test_punctuation_and_duplicates():
    assert toc("# What's new?\n# What's new?") == "- [What's new?](#whats-new)\n- [What's new?](#whats-new-1)"


def test_code_block_ignored():
    assert toc("# Real\n```\n# not a heading\n```") == "- [Real](#real)"


def test_none():
    assert toc("no headings here") == ""

"""Task: Write `html_to_text(html)` that removes tags, drops the contents of <script> and <style> elements entirely, turns <br> and the end of <p>, <div>, <li> and <h1>-<h6> into newlines, unescapes HTML entities, collapses runs of spaces within a line and strips each line, and removes blank lines."""

import html as _html
import re


def html_to_text(html):
    s = re.sub(r"(?is)<(script|style)\b.*?</\1\s*>", "", html)
    s = re.sub(r"(?i)<br\s*/?>", "\n", s)
    s = re.sub(r"(?i)</(p|div|li|h[1-6])\s*>", "\n", s)
    s = re.sub(r"<[^>]+>", "", s)
    s = _html.unescape(s)
    lines = [re.sub(r"[ \t\xa0]+", " ", line).strip() for line in s.split("\n")]
    return "\n".join(line for line in lines if line)


def test_paragraphs():
    assert html_to_text("<p>Hello <b>world</b></p><p>Bye</p>") == "Hello world\nBye"


def test_script_style_removed():
    html = "<style>p{color:red}</style><p>x</p><script>alert('<p>')</script>"
    assert html_to_text(html) == "x"


def test_entities_and_br():
    assert html_to_text("Fish &amp; chips<br/>5 &lt; 6&nbsp;&nbsp;ok") == "Fish & chips\n5 < 6 ok"


def test_list():
    assert html_to_text("<ul><li>one</li><li> two </li></ul>") == "one\ntwo"


def test_case_insensitive():
    assert html_to_text("<SCRIPT>x</SCRIPT><DIV>y</DIV>") == "y"

"""Task: Write `sentences(text)` that splits text into sentences ending in ".", "!" or "?" (possibly followed by closing quotes or brackets), when followed by whitespace and an uppercase letter, digit or quote, or by the end of the text. It must not split after common abbreviations (Mr., Mrs., Dr., e.g., i.e., etc., vs.) or after single capital initials such as "J.". Return stripped sentences; a trailing fragment without punctuation is kept."""

import re

ABBREV = {"mr.", "mrs.", "ms.", "dr.", "e.g.", "i.e.", "etc.", "vs.", "prof.", "st."}


def sentences(text):
    out, start = [], 0
    for m in re.finditer(r"[.!?]+['\")\]]*(?=\s+['\"(A-Z0-9]|\s*$)", text):
        end = m.end()
        last_word = text[start:m.start() + 1].split()[-1].lower() if text[start:m.start() + 1].split() else ""
        if m.group().startswith(".") and (last_word in ABBREV or re.fullmatch(r"[a-z]\.", last_word)):
            continue
        piece = text[start:end].strip()
        if piece:
            out.append(piece)
        start = end
    rest = text[start:].strip()
    if rest:
        out.append(rest)
    return out


def test_basic():
    assert sentences("Hi there. How are you? Fine!") == ["Hi there.", "How are you?", "Fine!"]


def test_abbreviations():
    assert sentences("Dr. Smith met Mr. Jones. They talked.") == ["Dr. Smith met Mr. Jones.", "They talked."]


def test_initials_and_eg():
    assert sentences("J. R. Tolkien wrote books, e.g. The Hobbit. Read it.") == [
        "J. R. Tolkien wrote books, e.g. The Hobbit.", "Read it."]


def test_quotes_and_fragment():
    assert sentences('He said "Stop!" Then left. and more') == ['He said "Stop!"', "Then left. and more"]


def test_numbers_and_ellipsis():
    assert sentences("Wait... 3 people came. Done") == ["Wait...", "3 people came.", "Done"]

"""Task: Write `normalize_phone(raw, default_country="1")` that turns phone numbers written in common ways ("(555) 123-4567", "555.123.4567", "+44 20 7946 0958", "0044 20 7946 0958", "1-555-123-4567") into E.164 form "+<country><number>". A number without a country prefix gets default_country. The result must have 8 to 15 digits after "+", otherwise ValueError; letters also raise ValueError."""

import re


def normalize_phone(raw, default_country="1"):
    s = raw.strip()
    if re.search(r"[A-Za-z]", s):
        raise ValueError(f"letters in phone number: {raw!r}")
    plus = s.startswith("+")
    digits = re.sub(r"\D", "", s)
    if plus:
        full = digits
    elif digits.startswith("00"):
        full = digits[2:]
    elif default_country == "1" and len(digits) == 11 and digits.startswith("1"):
        full = digits
    else:
        full = default_country + digits
    if not 8 <= len(full) <= 15:
        raise ValueError(f"bad phone number length: {raw!r}")
    return "+" + full


import pytest


def test_us_formats():
    for raw in ["(555) 123-4567", "555.123.4567", "1-555-123-4567", "+1 555 123 4567"]:
        assert normalize_phone(raw) == "+15551234567"


def test_international():
    assert normalize_phone("+44 20 7946 0958") == "+442079460958"
    assert normalize_phone("0044 20 7946 0958") == "+442079460958"


def test_default_country():
    assert normalize_phone("030 1234567", default_country="49") == "+490301234567"


def test_too_short():
    with pytest.raises(ValueError):
        normalize_phone("123")


def test_letters():
    with pytest.raises(ValueError):
        normalize_phone("1-800-FLOWERS")

"""Task: Write `justify(words, width)` that lays words out in fully justified lines of exactly `width` characters: extra spaces are spread as evenly as possible, with the leftmost gaps getting more. A line with one word, and the last line, are left-aligned and padded with spaces on the right. A word longer than width raises ValueError."""

def justify(words, width):
    if any(len(w) > width for w in words):
        raise ValueError("word longer than width")
    lines, cur, length = [], [], 0
    for w in words:
        if cur and length + len(cur) + len(w) > width:
            lines.append(cur)
            cur, length = [], 0
        cur.append(w)
        length += len(w)
    if cur:
        lines.append(cur)
    out = []
    for i, line in enumerate(lines):
        if i == len(lines) - 1 or len(line) == 1:
            out.append(" ".join(line).ljust(width))
            continue
        spaces = width - sum(len(w) for w in line)
        gaps = len(line) - 1
        q, r = divmod(spaces, gaps)
        s = ""
        for j, w in enumerate(line[:-1]):
            s += w + " " * (q + (1 if j < r else 0))
        out.append(s + line[-1])
    return out


import pytest


def test_example():
    words = "This is an example of text justification.".split()
    assert justify(words, 16) == ["This    is    an", "example  of text", "justification.  "]


def test_uneven_gaps_go_left():
    assert justify(["a", "b", "c", "dddd"], 7) == ["a  b  c", "dddd   "]


def test_single_word_line():
    assert justify(["hello", "world"], 6) == ["hello ", "world "]


def test_too_long():
    with pytest.raises(ValueError):
        justify(["abcdefg"], 5)


def test_empty():
    assert justify([], 5) == []

"""Task: Write `markdown_table(rows, headers, align=None)` that renders a list of rows (lists of values) as a GitHub Markdown table with columns padded to equal width. `align` is an optional list of "l", "r" or "c" per column, shown in the separator row as ":---", "---:" or ":---:" and applied to the padding. Values are converted with str(); a "|" inside a value is escaped with a backslash. Rows with the wrong number of cells raise ValueError."""

def markdown_table(rows, headers, align=None):
    ncol = len(headers)
    align = align or ["l"] * ncol
    if len(align) != ncol or any(a not in "lrc" for a in align):
        raise ValueError("bad align")
    cells = [[str(h).replace("|", "\\|") for h in headers]]
    for r in rows:
        if len(r) != ncol:
            raise ValueError(f"row has {len(r)} cells, expected {ncol}")
        cells.append([str(v).replace("|", "\\|") for v in r])
    widths = [max(3, max(len(row[i]) for row in cells)) for i in range(ncol)]

    def pad(text, w, a):
        return text.rjust(w) if a == "r" else text.center(w) if a == "c" else text.ljust(w)

    def line(row):
        return "| " + " | ".join(pad(t, w, a) for t, w, a in zip(row, widths, align)) + " |"

    seps = []
    for w, a in zip(widths, align):
        dash = "-" * w
        seps.append(":" + dash[1:] if a == "l" else dash[:-1] + ":" if a == "r" else ":" + dash[2:] + ":")
    return "\n".join([line(cells[0]), "| " + " | ".join(seps) + " |"] + [line(r) for r in cells[1:]])


import pytest


def test_basic():
    out = markdown_table([["apple", 3], ["kiwi", 12]], ["fruit", "n"], align=["l", "r"])
    assert out == "| fruit |   n |\n| :---- | --: |\n| apple |   3 |\n| kiwi  |  12 |"


def test_default_left():
    assert markdown_table([[1]], ["x"]) == "| x   |\n| :-- |\n| 1   |"


def test_center():
    out = markdown_table([["ab"]], ["title"], align=["c"])
    assert out.splitlines()[1] == "| :---: |"


def test_escape_pipe():
    assert "a\\|b" in markdown_table([["a|b"]], ["h"])


def test_bad_row():
    with pytest.raises(ValueError):
        markdown_table([[1, 2]], ["only"])
